<div class="p-6 space-y-4"><h1 class="text-2xl font-bold">Grade Rules</h1><form wire:submit="save" class="grid grid-cols-4 gap-2"><input wire:model="name" placeholder="Name"><input wire:model="minimum_percentage" placeholder="Min %"><input wire:model="maximum_percentage" placeholder="Max %"><input wire:model="letter_grade" placeholder="Letter"><input wire:model="grade_point" placeholder="Point"><button class="bg-blue-600 text-white p-2">Add rule</button></form><table class="w-full"><tbody>@foreach($rules as $r)<tr><td>{{$r->name}}</td><td>{{$r->minimum_percentage}}–{{$r->maximum_percentage}}</td><td>{{$r->letter_grade}} ({{$r->grade_point}})</td><td><button wire:click="toggle({{$r->id}})">{{$r->active?'Deactivate':'Activate'}}</button></td></tr>@endforeach</tbody></table></div>
